// The one list of images the public site uses (#162, captured 2026-10-16).
//
// kind "screen"       = a screenshot of the current CAOSCare software, taken from a
//                       scratch database: demo seed, a sample facility, the public
//                       demo room, and a paused simulated 75-resident community.
//                       Every name, room and record is sample or simulated data.
// kind "illustration" = a drawing of how a built capability is used.
// kind "concept"      = a drawing of a capability that is not built yet.
// Illustrations are generated by frontend/scripts/generate_public_illustrations.py.
// Retake a screen when the screen it shows changes.

const screen = (file, width, height, alt) => ({ kind: "screen", src: `/media/screens/${file}.jpg`, width, height, alt });
const drawing = (kind) => (file, alt) => ({ kind, src: `/media/illustrations/${file}.svg`, width: 1600, height: 900, alt });
const illustration = drawing("illustration");
const concept = drawing("concept");

